import { ProviderError } from "../../runtime/error.js";
export const closed = new ProviderError("file already closed");
export const exists = new ProviderError("file already exists");
export const invalid = new ProviderError("invalid argument");
export const notExists = new ProviderError("file does not exist");
export const permission = new ProviderError("permission denied");
export const unsupported = new ProviderError("unsupported operation");
export function errnoMatchesSentinel(value, target) {
    if (target === permission) {
        return value === 13n || value === 1n;
    }
    if (target === exists) {
        return value === 17n || value === 39n;
    }
    if (target === notExists) {
        return value === 2n;
    }
    if (target === unsupported) {
        return value === 38n || value === 95n;
    }
    return false;
}
